/* =========================================================
   GOOGLE ANALYTICS TRACKING
   ========================================================= */

function track(eventName, params={}) {
  // The quiz will still work even if Google Analytics
  // is blocked or unavailable.
  if (typeof gtag === "function") {
    gtag("event", eventName, params);
  }
}

function quizContext() {
  return {
    quiz_subject: subject.value,
    question_order: order.value,
    total_questions: set.length
  };
}



/* =========================================================
   MOODLE-STYLE QUESTION NAVIGATION
   ========================================================= */

function questionNavState(index){

  const x=set[index];
  const st=state[index];

  if(index===i){
    return "current";
  }

  if(!st){
    return "unanswered";
  }

  if(x.answer===null){
    return "flagged";
  }

  return st.ok ? "correct" : "incorrect";
}


function renderQuestionNavigator(){

  if(!questionNav) return;

  questionNav.innerHTML="";

  const frag=document.createDocumentFragment();

  set.forEach((x,index)=>{

    const b=document.createElement("button");

    const navState=questionNavState(index);

    b.type="button";
    b.className=`nav-question nav-${navState}`;
    b.textContent=String(index+1);

    b.setAttribute(
      "aria-label",
      `Go to question ${index+1}: ${x.sub || subject.value}`
    );

    if(index===i){
      b.setAttribute("aria-current","true");
    }

    // Useful on desktop when hovering over a question number.
    b.title=
      `Question ${index+1}`+
      `${x.sub ? " • "+x.sub : ""}`+
      `${x.id ? " • Original "+x.id : ""}`;

    b.addEventListener("click",()=>{

      if(index===i) return;

      const fromQuestion=i+1;

      i=index;

      track("question_navigated",{
        ...quizContext(),
        from_question:fromQuestion,
        to_question:index+1,
        target_subject:x.sub || subject.value
      });

      render();

      // Keep the selected question visible inside a long navigator.
      requestAnimationFrame(()=>{
        const current=
          questionNav.querySelector('[aria-current="true"]');

        if(current){
          current.scrollIntoView({
            block:"nearest",
            inline:"nearest"
          });
        }
      });
    });

    frag.appendChild(b);
  });

  questionNav.appendChild(frag);

  const answered=state.filter(Boolean).length;

  if(navSummary){
    navSummary.textContent=
      `${answered} of ${set.length} visited/answered`;
  }
}


function updateQuestionNavigator(){

  if(!questionNav) return;

  const buttons=questionNav.querySelectorAll(".nav-question");

  // If the set changed, rebuild the whole navigation grid.
  if(buttons.length!==set.length){
    renderQuestionNavigator();
    return;
  }

  buttons.forEach((b,index)=>{

    const navState=questionNavState(index);

    b.className=`nav-question nav-${navState}`;

    if(index===i){
      b.setAttribute("aria-current","true");
    }else{
      b.removeAttribute("aria-current");
    }
  });

  const answered=state.filter(Boolean).length;

  if(navSummary){
    navSummary.textContent=
      `${answered} of ${set.length} visited/answered`;
  }
}


function setNavigatorOpen(open){

  if(!questionNavWrap || !toggleNav) return;

  questionNavWrap.hidden=!open;
  toggleNav.textContent=open ? "Hide" : "Show";
  toggleNav.setAttribute("aria-expanded",String(open));
}


/* =========================================================
   QUIZ
   ========================================================= */

function esc(s){
  return String(s).replace(/[&<>"']/g,c=>({
    "&":"&amp;",
    "<":"&lt;",
    ">":"&gt;",
    "\"":"&quot;",
    "'":"&#039;"
  }[c]))
}

function shuffle(a){
  let b=a.slice();

  for(let x=b.length-1;x>0;x--){
    let j=Math.floor(Math.random()*(x+1));
    [b[x],b[j]]=[b[j],b[x]];
  }

  return b;
}


function build(){

  const s=subject.value;

  set=s==="ALL"
    ?Object.entries(BANK).flatMap(
      ([sub,arr])=>arr.map(x=>({...x,sub}))
    )
    :BANK[s].map(x=>({...x,sub:s}));

  if(order.value==="shuffle") set=shuffle(set);

  i=0;
  score=0;
  scored=0;
  state=set.map(()=>null);
  quizStarted=false;

  quiz.hidden=false;
  finish.hidden=true;

  renderQuestionNavigator();
  render();
}


function render(){

  const x=set[i],
        st=state[i];

  prog.textContent=`Question ${i+1} of ${set.length}`;
  scoreEl.textContent=`Score: ${score} / ${scored}`;

  bar.style.width=`${((i+1)/set.length)*100}%`;

  let lab=
    x.status==="corrected"
      ?"Corrected"
      :x.status==="flagged"
      ?"Flagged / unscored"
      :"Validated";

  meta.innerHTML=
    `${esc(x.sub)} • Question ${x.id}
     <span class="status">${lab}</span>`;

  q.textContent=x.q;

  answers.innerHTML="";
  feedback.hidden=true;
  feedback.innerHTML="";

  prev.disabled=i===0;

  x.opts.forEach((opt,j)=>{

    let b=document.createElement("button");

    b.type="button";
    b.className="answer";
    b.textContent=`${LETTERS[j]||j+1}. ${opt}`;

    if(st){
      b.disabled=true;

      if(x.answer===j)
        b.classList.add("correct");

      if(st.choice===j && x.answer!==j)
        b.classList.add("wrong");
    }

    b.addEventListener("click",()=>choose(j));

    answers.appendChild(b);
  });

  if(st) show(x,st);

  next.disabled=false;

  next.textContent=
    i===set.length-1
      ?"Finish"
      :"Next";

  updateQuestionNavigator();
}


function choose(choice){

  if(state[i]) return;

  const x=set[i];

  /* Track first interaction with a quiz */
  if(!quizStarted){

    quizStarted=true;

    track("quiz_started",{
      ...quizContext(),
      starting_subject:x.sub
    });
  }


  let result;

  if(x.answer===null){

    state[i]={
      choice,
      flag:true
    };

    result="unscored";

  } else {

    const ok=choice===x.answer;

    state[i]={
      choice,
      ok
    };

    scored++;

    if(ok) score++;

    result=ok ? "correct" : "incorrect";
  }


  /* Track every answered question */
  track("question_answered",{

    ...quizContext(),

    question_id:String(x.id),

    question_number:i+1,

    question_subject:x.sub,

    question_status:x.status,

    answer_result:result

  });


  render();
}



function resetCurrentQuestion(){

  const x=set[i];
  const st=state[i];

  if(!st) return;

  // Only a normal incorrectly answered question can be retried.
  // Correct answers and flagged/unscored questions remain unchanged.
  if(x.answer===null || st.ok) return;

  track("question_reset",{
    ...quizContext(),
    question_id:String(x.id),
    question_number:i+1,
    question_subject:x.sub,
    previous_result:"incorrect"
  });

  // The first wrong attempt increased the scored denominator.
  // Undo only that question before allowing another attempt.
  scored=Math.max(0,scored-1);

  // Clear only the current question.
  state[i]=null;

  render();
}


function show(x,st){

  feedback.hidden=false;

  if(x.answer===null){

    feedback.innerHTML=
      `<strong class="warn">
       ⚠ This question is not scored.
       </strong>

       <br><br>

       ${esc(x.explanation)}

       <div class="evidence">

       <strong>Syllabus check:</strong>
       ${esc(x.evidence)}

       <span class="ref">
       CLPE Part One syllabus, p. ${x.page}
       </span>

       </div>`;

    return;
  }


  const ans=x.opts[x.answer];

  const head=
    st.ok
      ?`<strong class="good">✓ Correct.</strong>`
      :`<strong class="bad">✗ Incorrect.</strong>`;


  const corr=
    x.status==="corrected"
      ?`<br>
        <span class="warn">
        <strong>Correction:</strong>
        the supplied key/marking was not retained because
        the syllabus supports this answer instead.
        </span>`
      :"";


  feedback.innerHTML=
    `${head}

     <br>

     <strong>
     Verified answer:
     ${LETTERS[x.answer]||x.answer+1}.
     ${esc(ans)}
     </strong>

     ${corr}

     <br><br>

     <strong>Why this is correct:</strong>

     <br>

     ${esc(x.explanation)}

     <div class="evidence">

     <strong>What the syllabus says:</strong>

     ${esc(x.evidence)}

     <span class="ref">
     CLPE Part One syllabus, p. ${x.page}
     </span>

     </div>`;

  // If the learner chose a wrong answer, allow only this question
  // to be reset and attempted again.
  // if(!st.ok){

  //   feedback.innerHTML += `
  //     <div class="retry-wrap">
  //       <button
  //         type="button"
  //         id="retry-question"
  //         class="retry-question">
  //         ↻ Try this question again
  //       </button>
  //     </div>
  //   `;

  //   document
  //     .getElementById("retry-question")
  //     .addEventListener("click",resetCurrentQuestion);
  // }
}


/* =========================================================
   NAVIGATION + ANALYTICS
   ========================================================= */

next.addEventListener("click",()=>{

  if(i<set.length-1){

    i++;
    render();

  } else {

    const percentage=
      scored>0
        ?Number(((score/scored)*100).toFixed(1))
        :0;


    /* Track completed quiz */
    track("quiz_completed",{

      ...quizContext(),

      quiz_score:score,

      scored_questions:scored,

      answered_questions:
        state.filter(Boolean).length,

      quiz_percentage:percentage

    });


    quiz.hidden=true;
    finish.hidden=false;

    final.textContent=
      `You scored ${score} out of ${scored} scored questions. `+
      `Flagged questions were excluded.`;
  }
});


prev.addEventListener("click",()=>{

  if(i>0){

    i--;

    render();
  }
});


restart.addEventListener("click",()=>{

  const x=set[i];
  const st=state[i];

  // Nothing to clear if the current question has not been answered.
  if(!st){
    track("question_restart_clicked",{
      ...quizContext(),
      question_id:String(x.id),
      question_number:i+1,
      question_subject:x.sub,
      had_answer:false
    });

    render();
    return;
  }

  // If this was a scored question, undo only this question's
  // contribution to the current score before clearing it.
  if(x.answer!==null){

    scored=Math.max(0,scored-1);

    if(st.ok){
      score=Math.max(0,score-1);
    }
  }

  track("question_restarted",{
    ...quizContext(),
    question_id:String(x.id),
    question_number:i+1,
    question_subject:x.sub,
    previous_result:
      x.answer===null
        ?"unscored"
        :(st.ok ? "correct" : "incorrect")
  });

  // Clear only the current question.
  state[i]=null;

  render();
});


again.addEventListener("click",()=>{

  track("quiz_restarted",{

    ...quizContext(),

    restart_source:"completion"

  });

  build();
});


subject.addEventListener("change",()=>{

  track("subject_selected",{

    selected_subject:subject.value

  });

  build();
});


order.addEventListener("change",()=>{

  track("question_order_changed",{

    selected_order:order.value,

    selected_subject:subject.value

  });

  build();
});



if(toggleNav){
  toggleNav.addEventListener("click",()=>{
    setNavigatorOpen(questionNavWrap.hidden);
  });
}


build();